export function invoiceTitle(status: "pending" | "paid") {
  if (status === "pending") {
    return "Pending payment";
  }
  return "Paid invoice";
}

edits.newText:
export function invoiceTitle(status: "pending" | "paid") {
  if (status === "pending") {
    return "Awaiting payment";
  }
  return "Paid invoice";
}

